// Sync root canonical docs into the Docusaurus docs tree.
//
//   SPEC.md       → website/docs/spec.md                 (NORMATIVE badge + freeze banner)
//   EXTENSIONS.md → website/docs/extensions-registry.md  (full registry render;
//                   the hand-authored /docs/extensions pages are the browsable view)
//   CHANGELOG.md  → website/docs/changelog.md
//
// Idempotent and deterministic: run it any number of times, output depends
// only on the source files. Pure Node, no dependencies.
// The generated files carry a DO-NOT-EDIT banner; edit the root files instead.

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const DOCS = join(ROOT, 'website', 'docs');

const GH_BLOB = 'https://github.com/JordanNewell/dot_curt/blob/main';

// Repo-relative markdown link targets that map to a docs-site route; everything
// else that looks like a repo file goes to the GitHub blob so links stay live.
const SITE_ROUTES = {
	'EXTENSIONS.md': '/docs/extensions',
	'conformance/README.md': '/docs/conformance',
	'conformance/': '/docs/conformance',
};

function rewriteLinks(markdown) {
	return markdown.replace(/\]\(([^)\s]+)\)/g, (match, target) => {
		if (target.startsWith('http://') || target.startsWith('https://') || target.startsWith('#') || target.startsWith('/')) {
			return match;
		}
		if (SITE_ROUTES[target]) return `](${SITE_ROUTES[target]})`;
		if (target.endsWith('.md') || target.endsWith('.json') || target.endsWith('.ts')) {
			return `](${GH_BLOB}/${target})`;
		}
		return match;
	});
}

function yaml(s) {
	return `"${s.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`;
}

function frontmatter(id, slug, title, description) {
	return [
		'---',
		`id: ${yaml(id)}`,
		`slug: ${yaml(slug)}`,
		`title: ${yaml(title)}`,
		`description: ${yaml(description)}`,
		'---',
		'',
	].join('\n');
}

/** Strip the leading H1 (frontmatter title covers it) and any leading blanks. */
function stripH1(markdown) {
	return markdown.replace(/^# [^\n]*\n/, '').replace(/^\n+/, '').trimEnd() + '\n';
}

function banner(source) {
	return `<!-- GENERATED by scripts/sync-spec-docs.mjs from ${source} — DO NOT EDIT. Edit the root file and re-run the script. -->\n\n`;
}

function sync({ source, target, id, slug, title, description, body }) {
	const raw = readFileSync(join(ROOT, source), 'utf8');
	const out =
		banner(source) +
		frontmatter(id, slug, title, description) +
		'\n' +
		body(rewriteLinks(stripH1(raw)));
	mkdirSync(dirname(target), { recursive: true });
	writeFileSync(target, out);
	console.log(`synced ${source} -> ${target.replace(ROOT + '/', '')}`);
}

const FREEZE_BANNER = `:::caution[Version 1 — FROZEN]

The validation rules of format version 1 are frozen at release. Within
version 1 the format moves only through the
[extension registry](/docs/extensions); anything that would change how a
conforming v1 reader parses requires a new format version.

:::

`;

sync({
	source: 'SPEC.md',
	target: join(DOCS, 'spec.md'),
	id: 'spec',
	slug: 'spec',
	title: 'The .curt format — SPEC',
	description:
		'The normative .curt v1 specification: file shape, validation rules, extensions, bulk convention, versioning.',
	body: (md) => `:::info[NORMATIVE]

This document is the normative specification of the .curt format. When any
other page, schema, or prose disagrees with it, this document — and the
reference implementation \`parseCurt\` — decide.

:::

${FREEZE_BANNER}${md}`,
});

sync({
	source: 'EXTENSIONS.md',
	target: join(DOCS, 'extensions-registry.md'),
	id: 'extensions-registry',
	slug: 'extensions-registry',
	title: 'Extension registry — full text',
	description:
		'The full EXTENSIONS.md registry text: entry process, status rules, and the five registered extensions.',
	body: (md) => md,
});

sync({
	source: 'CHANGELOG.md',
	target: join(DOCS, 'changelog.md'),
	id: 'changelog',
	slug: 'changelog',
	title: 'Changelog',
	description: 'Release history for the .curt format spec and the curt-format package.',
	body: (md) => md,
});

console.log('done.');
